import json,pathlib
from PIL import Image,ImageDraw,ImageFont
p=pathlib.Path(__file__).resolve().parents[1];r=json.loads((p/'validacao/resultados.json').read_text(encoding='utf-8'))
lines=['# Validação da primeira versão funcional','', '13/11/2026 · Microsoft Edge / Chromium headless, em Windows.','', '## Resultado','', '| Largura | Carrossel visível | Toque | Overflow da página | Subrecursos iniciais |','|---|---|---|---|---|']
for v in r['viewports']:
 lines.append(f"| {v['width']} px | {v['carouselVisible']} imagem(ns) | {v['touch']} | Não | {v['initialResourceBytes']/1000:.1f} kB |")
lines += ['', 'Os valores de recursos são `encodedBodySize` dos subrecursos observados na primeira tela, antes do percurso pela página; não incluem o HTML (16,5 kB), cabeçalhos ou efeitos de compressão em produção. Incluem possíveis antecipações de imagens lazy do navegador. Não são nota Lighthouse nem medição em rede móvel.', '', '## Verificações aprovadas', '', '- Seis larguras sem overflow horizontal da página, inclusive depois das interações.', '- Mobile com cartão inicial compacto, ícone de localização e CTA “Quero conversar com a Pri”; foto WebP com `object-fit: cover` imediatamente antes do formulário. Tablet e desktop preservados, com comparação de pixels nas larguras 768, 1280 e 1440.', '- Identificação completa, profissão e CRECI presentes; retrato profissional no lugar da captura de Instagram.', '- Três imagens da seleção anterior; duas por tela a partir de 768 px e uma abaixo desse limite.', '- Setas, estados inicial/final e navegação por teclado (esquerda/direita, Home/End).', '- Gesto nativo de deslize emulado por eventos de toque CDP nas três larguras mobile.', '- Todas as imagens da página decodificadas, sem recursos com erro HTTP ou erros JavaScript.', '- Validação de telefone internacional, campos obrigatórios e consentimento desmarcado. Campos de qualificação opcionais disponíveis em bloco expansível.', '- Mensagem de validação explicita que não houve envio ou armazenamento; zero requisições POST durante os testes.', '- Zero requisições externas, cookies, localStorage ou sessionStorage nesta versão.', '- Leitura das UTMs permitidas na página atual, sem persistência ou transmissão.', '- Um H1, title, description, metadados Open Graph, imagem OG 1200 × 630, idioma pt-BR, robots noindex e dimensões das imagens.', '- Conteúdo em HTML acessível sem JavaScript, com envio desabilitado.', '- Preferência por movimento reduzido respeitada.', '- Function reservada testada como módulo: GET 405, POST 503 e `ok: false`.', '', '## Capturas', '', 'Os arquivos em `validacao/pagina-LARGURA.png` são capturas completas do navegador, anteriores ao preenchimento de dados sintéticos. `hero-LARGURA.png` registra a primeira tela e `carrossel-LARGURA.png` registra a galeria. As seis versões foram revisadas visualmente, com atenção a recortes, legibilidade e alinhamento.', '', '## Limites e pendências', '']
lines += ['- '+x for x in r['limitations']]
lines += ['- A autorização comercial do retrato continua pendente; a exibição atual é de revisão local.', '- Associação dos ambientes e direitos de uso precisam de confirmação antes da versão pública.', '- Integração real, credenciais, banco, privacidade final, Cloudflare e domínio continuam pendentes.', '- Não foi feita auditoria WCAG completa; foram verificados rótulos, foco, teclado, textos alternativos e movimento reduzido.', '- Cabeçalhos de segurança do Pages foram conferidos no código; sua aplicação no Cloudflare deve ser validada na primeira prévia remota autorizada.', '', '## Reproduzir o QA', '', 'O site não depende de Playwright. Para repetir somente os testes de desenvolvimento, usar uma instalação de Playwright já disponível e indicar `PLAYWRIGHT_MODULE` e, se necessário, `BROWSER_EXECUTABLE`; executar `node tools/test-browser.mjs`. O teste inicia e encerra seu próprio servidor em 127.0.0.1:4177 e não publica nada.', '', 'O JSON detalhado da execução está em `validacao/resultados.json`.']
(p/'docs/VALIDACAO.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
canvas=Image.new('RGB',(1440,1270),'#f5f1e9');d=ImageDraw.Draw(canvas);f=ImageFont.truetype('C:/Windows/Fonts/segoeuib.ttf',20)
for i,w in enumerate([320,375,430,768,1280,1440]):
 im=Image.open(p/f'validacao/hero-{w}.png');im.thumbnail((450,570))
 x=(i%3)*480+(480-im.width)//2;y=(i//3)*635+45
 canvas.paste(im,(x,y));d.text(((i%3)*480+20,(i//3)*635+10),f'{w} px',font=f,fill='#15363d')
canvas.save(p/'validacao/resumo-responsivo.jpg',quality=90)
